local WhalingCaptain = {}
local PRODUCTS = {
    whale_oil = { name = "Kitovo olje", harpoonCost = 1, time = 5, cost = 40, yield = 40, happiness = 1, description = "Kitovo olje za svetilke in milo." },
    whalebone = { name = "Kitove kosti", harpoonCost = 1, time = 6, cost = 60, yield = 50, prestige = 2, description = "Kitove kosti za korsete in okrasje." },
    ambergris = { name = "Ambra", harpoonCost = 1, silverCost = 1, time = 10, cost = 220, yield = 65, prestige = 6, happiness = 2, description = "Ambra za parfume in zdravila." },
    sperm_oil = { name = "Spermačetno olje", harpoonCost = 1, silverCost = 1, time = 13, cost = 480, yield = 75, prestige = 10, happiness = 2, description = "Spermačetno olje za fine svetilke." },
    silver_harpoon_catch = { name = "Srebrno harpunski ulov", harpoonCost = 1, silverCost = 1, time = 17, cost = 1000, yield = 88, prestige = 18, happiness = 4, description = "Ulov s srebrno harpuno za visoke plemiče." },
    royal_grand_whale = { name = "Kraljevski veliki kit ulov", harpoonCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, time = 25, cost = 2800, yield = 100, prestige = 50, happiness = 12, description = "Veliki kraljevski kit z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Kitolovska postaja", cost = { gold = 350, wood = 150, stone = 250 }, upkeep = 9, qualityBonus = 5 },
    whaling_harbor = { name = "Kitolovsko pristanišče", cost = { gold = 1300, wood = 300, stone = 500, iron = 10 }, upkeep = 32, qualityBonus = 18 },
    try_works = { name = "Kuhalnica", cost = { gold = 3000, wood = 400, stone = 800, silver = 50, fuel = 10 }, upkeep = 75, qualityBonus = 30 },
    royal_whaling_atelier = { name = "Kraljevski atelje kitolova", cost = { gold = 12000, wood = 700, stone = 1200, gold = 80, jewel = 25 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
WhalingCaptain.harpoonStock = 18; WhalingCaptain.silverStock = 8; WhalingCaptain.goldStock = 6; WhalingCaptain.jewelStock = 6
WhalingCaptain.productStock = {}; WhalingCaptain.buildings = {}; WhalingCaptain.maker = nil; WhalingCaptain.activeMaking = {}; WhalingCaptain.totalProducts = 0; WhalingCaptain.dayTimer = 0
function WhalingCaptain.init() WhalingCaptain.harpoonStock=18; WhalingCaptain.silverStock=8; WhalingCaptain.goldStock=6; WhalingCaptain.jewelStock=6; WhalingCaptain.productStock={}; WhalingCaptain.buildings={}; WhalingCaptain.maker=nil; WhalingCaptain.activeMaking={}; WhalingCaptain.totalProducts=0; WhalingCaptain.dayTimer=0; print("[WhalingCaptain] Royal Whaling Captain System initialized (6 products, 4 buildings)") end
function WhalingCaptain.hireMaker(n,s) s=s or math.random(55,90); local c=620+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WhalingCaptain.maker={name=n or ("Kitolovec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kitolovec najet: %s (spretnost: %d)",WhalingCaptain.maker.name,s),"success") end; return true end
function WhalingCaptain.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WhalingCaptain.build(id) local ok,e=WhalingCaptain.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WhalingCaptain.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WhalingCaptain.getQualityBonus() local b=0; for _,bd in ipairs(WhalingCaptain.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WhalingCaptain.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.harpoonCost and WhalingCaptain.harpoonStock<(d.harpoonCost or 0) then return false,"Premalo harpun" end; if d.silverCost and WhalingCaptain.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WhalingCaptain.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WhalingCaptain.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #WhalingCaptain.buildings==0 then return false,"Potrebna delavnica" end; if not WhalingCaptain.maker then return false,"Potreben kitolovec" end; return true end
function WhalingCaptain.make(pt,qty) qty=qty or 1; local ok,e=WhalingCaptain.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.harpoonCost then WhalingCaptain.harpoonStock=WhalingCaptain.harpoonStock-d.harpoonCost*qty end; if d.silverCost then WhalingCaptain.silverStock=WhalingCaptain.silverStock-d.silverCost*qty end; if d.goldCost then WhalingCaptain.goldStock=WhalingCaptain.goldStock-d.goldCost*qty end; if d.jewelCost then WhalingCaptain.jewelStock=WhalingCaptain.jewelStock-d.jewelCost*qty end; local t=d.time; if WhalingCaptain.maker then t=math.max(1,t-math.floor(WhalingCaptain.maker.skill/12)) end; table.insert(WhalingCaptain.activeMaking,{id="whale_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,yield=d.yield or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WhalingCaptain.completeMaking(m) local q=1.0+(WhalingCaptain.getQualityBonus()/100); if WhalingCaptain.maker then q=q+(WhalingCaptain.maker.skill/150) end; q=math.min(2.5,q); WhalingCaptain.productStock[m.productType]=(WhalingCaptain.productStock[m.productType] or 0)+m.quantity; WhalingCaptain.totalProducts=WhalingCaptain.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WhalingCaptain.maker then WhalingCaptain.maker.itemsMade=WhalingCaptain.maker.itemsMade+m.quantity; if math.random()<0.25 then WhalingCaptain.maker.skill=math.min(100,WhalingCaptain.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kit produkt pridobljen: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"whale.completed",{productName=m.productName,yield=m.yield,prestige=m.prestige,happiness=m.happiness}) end end
function WhalingCaptain.update(dt) if not _G.state then return end; WhalingCaptain.dayTimer=WhalingCaptain.dayTimer+dt; if WhalingCaptain.dayTimer>=30 then WhalingCaptain.dayTimer=0; for i=#WhalingCaptain.activeMaking,1,-1 do local m=WhalingCaptain.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WhalingCaptain.completeMaking(m); table.remove(WhalingCaptain.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WhalingCaptain.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WhalingCaptain.maker then tu=tu+20 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WhalingCaptain.getStats() return {harpoonStock=WhalingCaptain.harpoonStock,silverStock=WhalingCaptain.silverStock,goldStock=WhalingCaptain.goldStock,jewelStock=WhalingCaptain.jewelStock,productStock=WhalingCaptain.productStock,numBuildings=#WhalingCaptain.buildings,hasMaker=WhalingCaptain.maker~=nil,makerName=WhalingCaptain.maker and WhalingCaptain.maker.name or "—",makerSkill=WhalingCaptain.maker and WhalingCaptain.maker.skill or 0,activeMaking=#WhalingCaptain.activeMaking,totalProducts=WhalingCaptain.totalProducts} end
return WhalingCaptain
